import { DeleteOutline, EditOutlined } from '@mui/icons-material'
import { Box, ButtonBase, Card, Divider, Stack, Tooltip, Typography } from '@mui/material'

import { type ClubReview } from 'src/responses/review'

import ReviewKeyword from '../ReviewKeyword'
import SemesterChip from '../SemesterChip'

interface MyPageReviewCardProps extends ClubReview {
  onDelete: (reviewId: number, clubId: number) => void
  onEdit: (reviewId: number, clubId: number) => void
}

const MyPageReviewCard: React.FC<MyPageReviewCardProps> = review => {
  const {
    id,
    clubName,
    clubDescription,
    year,
    semester,
    content,
    keywords,
    recommendedPerson,
    isHiddenByClub,
    clubId,
    userNickname,
    onDelete,
    onEdit
  } = review

  const handleEditButtonClick: React.MouseEventHandler<HTMLButtonElement> = _event => {
    onEdit(id, clubId)
  }

  const handleDeleteButtonClick: React.MouseEventHandler<HTMLButtonElement> = _event => {
    onDelete(id, clubId)
  }

  return (
    <Card
      sx={{
        p: '34px 36px 13px',
        borderRadius: '10px',
        boxShadow: '0px 2px 2px 0px rgba(159, 162, 191, 0.25), 0px 9px 16px 0px rgba(159, 162, 191, 0.18)',
        display: 'flex',
        flexDirection: 'column',
        gap: '14px'
      }}
    >
      <Stack direction="row" justifyContent="space-between" alignItems="flex-start">
        <Stack spacing="3px">
          {clubName && (
            <Typography
              sx={{
                fontFamily: 'Pretendard',
                fontSize: '13px',
                fontWeight: 400,
                color: '#000000',
                lineHeight: 1.2
              }}
            >
              {clubName}
            </Typography>
          )}
          {clubDescription && (
            <Typography
              sx={{
                fontFamily: 'Pretendard',
                fontSize: '14px',
                fontWeight: 400,
                color: 'rgba(34, 51, 84, 0.7)',
                lineHeight: 1.2
              }}
            >
              {clubDescription}
            </Typography>
          )}
        </Stack>
        <SemesterChip year={year} semester={semester} />
      </Stack>

      <Typography
        sx={{
          fontFamily: 'Pretendard',
          fontSize: '13px',
          lineHeight: '1.5',
          color: '#000000'
        }}
      >
        {content}
      </Typography>

      {keywords && keywords.length > 0 && (
        <Stack spacing="3px">
          {keywords.map(keyword => (
            <ReviewKeyword key={keyword.id} keyword={keyword} />
          ))}
        </Stack>
      )}

      <Stack direction="row" justifyContent="space-between" alignItems="center" sx={{ pt: 0.5 }}>
        <Typography
          sx={{
            fontFamily: 'Pretendard',
            fontSize: '13px',
            color: '#FF9393'
          }}
        >
          {recommendedPerson ? `# ${recommendedPerson}에게 추천!` : ''}
        </Typography>
        {userNickname && (
          <Typography
            sx={{
              fontFamily: 'Pretendard',
              fontSize: '13px',
              color: '#AAAAAA'
            }}
          >
            from. {userNickname}
          </Typography>
        )}
      </Stack>

      <Divider sx={{ borderColor: 'rgba(159, 162, 191, 0.25)' }} />

      <Stack direction="row" justifyContent="space-between" alignItems="center">
        <Box>
          {isHiddenByClub === true && (
            <Tooltip
              title={
                <>
                  이 리뷰는 비공개 처리되었습니다.
                  <br />
                  동아리 운영진에게 문의하세요.
                </>
              }
              arrow
            >
              <Box
                sx={{
                  backgroundColor: '#B1B1B1',
                  borderRadius: '16px',
                  padding: '3px 7px',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  cursor: 'default'
                }}
              >
                <Typography
                  sx={{
                    fontFamily: 'Pretendard',
                    fontSize: '13px',
                    fontWeight: 700,
                    color: '#FFFFFF'
                  }}
                >
                  비공개
                </Typography>
              </Box>
            </Tooltip>
          )}
        </Box>
        <Stack direction="row" spacing={2}>
          <ButtonBase
            type="button"
            onClick={handleEditButtonClick}
            sx={{
              display: 'flex',
              alignItems: 'center',
              gap: 0.5
            }}
          >
            <EditOutlined sx={{ fontSize: 18 }} />
            <Typography
              sx={{
                fontFamily: 'Pretendard',
                fontSize: '13px',
                fontWeight: 700
              }}
            >
              수정하기
            </Typography>
          </ButtonBase>
          <ButtonBase
            type="button"
            onClick={handleDeleteButtonClick}
            sx={{
              display: 'flex',
              alignItems: 'center',
              gap: 0.5
            }}
          >
            <DeleteOutline sx={{ fontSize: 18 }} />
            <Typography
              sx={{
                fontFamily: 'Pretendard',
                fontSize: '13px',
                fontWeight: 700
              }}
            >
              삭제하기
            </Typography>
          </ButtonBase>
        </Stack>
      </Stack>
    </Card>
  )
}

export default MyPageReviewCard
